CREATE DEFINER=`socialhousing`@`localhost` PROCEDURE `export_recent_data`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE tbl_name VARCHAR(255);
    DECLARE cur CURSOR FOR 
        SELECT TABLE_NAME 
        FROM INFORMATION_SCHEMA.TABLES 
        WHERE TABLE_SCHEMA = 'socialhousing';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO tbl_name;
        IF done THEN
            LEAVE read_loop;
        END IF;

        SET @sql = CONCAT(
            'SELECT * FROM ', tbl_name, 
            ' WHERE updated_at >= "2024-03-05"',
            ' INTO OUTFILE "/tmp/', tbl_name, '_recent.sql"',
            ' FIELDS TERMINATED BY "," OPTIONALLY ENCLOSED BY \'"\' LINES TERMINATED BY "\n"'
        );

        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;

    END LOOP;

    CLOSE cur;
END

CREATE DEFINER=`socialhousing`@`localhost` PROCEDURE `SyncTables`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE table_name VARCHAR(255);
    DECLARE batch_size INT DEFAULT 1000;
    DECLARE total_size BIGINT DEFAULT 0;
    DECLARE max_size BIGINT DEFAULT 1024*1024*1024; -- 1GB
    
    -- 테이블 목록 커서
    DECLARE table_cursor CURSOR FOR 
        SELECT TABLE_NAME 
        FROM INFORMATION_SCHEMA.TABLES 
        WHERE TABLE_SCHEMA = @OLD_DB;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    -- 로그 테이블 생성
    CREATE TABLE IF NOT EXISTS sync_log (
        id INT AUTO_INCREMENT PRIMARY KEY,
        sync_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        table_name VARCHAR(255),
        records_synced INT,
        message TEXT
    );
    
    OPEN table_cursor;
    
    table_loop: LOOP
        FETCH table_cursor INTO table_name;
        IF done THEN
            LEAVE table_loop;
        END IF;
        
        -- 동기화 쿼리 생성
        SET @sync_query = CONCAT(
            'INSERT INTO ', @NEW_DB, '.', table_name,
            ' SELECT * FROM ', @OLD_DB, '.', table_name,
            ' WHERE updated_at > ''', @SYNC_DATE, '''',
            ' ON DUPLICATE KEY UPDATE '
        );
        
        -- 컬럼 정보 가져오기
        SET @columns = (
            SELECT GROUP_CONCAT(COLUMN_NAME)
            FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = @OLD_DB
            AND TABLE_NAME = table_name
        );
        
        -- UPDATE 구문 생성
        SET @update_clause = (
            SELECT GROUP_CONCAT(
                CONCAT(COLUMN_NAME, '=VALUES(', COLUMN_NAME, ')')
            )
            FROM INFORMATION_SCHEMA.COLUMNS
            WHERE TABLE_SCHEMA = @OLD_DB
            AND TABLE_NAME = table_name
        );
        
        SET @sync_query = CONCAT(@sync_query, @update_clause);
        
        -- 예상 데이터 크기 확인
        SET @size_check = CONCAT(
            'SELECT SUM(LENGTH(CONCAT(',
            @columns,
            '))) INTO @batch_size FROM ', 
            @OLD_DB, '.', table_name,
            ' WHERE updated_at > ''', @SYNC_DATE, ''''
        );
        
        PREPARE stmt FROM @size_check;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
        
        -- 용량 제한 체크
        IF (total_size + @batch_size) > max_size THEN
            INSERT INTO sync_log (table_name, message)
            VALUES (table_name, '용량 제한 초과로 중단');
            LEAVE table_loop;
        END IF;
        
        -- 동기화 실행
        PREPARE stmt FROM @sync_query;
        EXECUTE stmt;
        
        -- 로그 기록
        SET @rows = ROW_COUNT();
        INSERT INTO sync_log (table_name, records_synced, message)
        VALUES (table_name, @rows, '동기화 완료');
        
        SET total_size = total_size + @batch_size;
        
        DEALLOCATE PREPARE stmt;
    END LOOP;
    
    CLOSE table_cursor;
    
    -- 최종 결과 출력
    SELECT 
        table_name,
        records_synced,
        message,
        sync_time
    FROM sync_log
    ORDER BY sync_time DESC;
END
